Looking at Demo 1 more carefully:
- First 4 appears at (0,4)
- With background=0
- Output is 4x2 = [[4,0],[0,4],[4,4],[4,0]]
- This is exactly columns 4-5, rows 0-3 of the input

The pattern is: Find the first foreground cell (top-leftmost by row,col order), find its connected component (foreground-only), compute the minimal bounding box of that component, and extract it.

```python
def transform(grid):
    # Find background (most common value)
    from collections import Counter
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    background = max(counts, key=counts.get)

    # Find bounds of connected component from first foreground cell
    first_r, first_c = None, None
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                first_r, first_c = r, c
                break
        if first_r is not None:
            break

    if first_r is None:
        return []

    # BFS to find all connected foreground cells
    min_r, max_r, min_c, max_c = first_r, first_r, first_c, first_c
    visited = set()
    queue = [(first_r, first_c)]

    while queue:
        r, c = queue.pop(0)
        if (r, c) in visited:
            continue
        visited.add((r, c))
        min_r = min(min_r, r)
        max_r = max(max_r, r)
        min_c = min(min_c, c)
        max_c = max(max_c, c)

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] != background and (nr, nc) not in visited:
                    queue.append((nr, nc))

    # Extract the bounding box
    return [
        [grid[r][c] for c in range(min_c, max_c + 1)]
        for r in range(min_r, max_r + 1)
    ]
